-- JankFFI: a usable native-call layer built from the VM's own dispatcher.
--
-- Background, all established on hardware:
--   * LuaJIT's lj_vm_ffi_call is ABSENT from this build, so every direct ffi
--     call aborts the process. Proof is a direct read, not inference: the
--     single call site main+0x46994 branches to main+0x56ef8, which is eight
--     bytes of 00000000 alignment padding between a ret at +0x56ef4 and the
--     next function at +0x56f00, so the call executes UDF #0. Root cause: the
--     VM was generated by buildvm with the DynASM FFI conditional off while
--     the C library has LJ_HASFFI=1, so every `.if FFI` block is missing.
--     bl.ffi_call rebuilds that dispatch out of SDK gadgets and exposes it as
--     plain Lua closures -- NOT as callable cdata, because the same root
--     cause leaves ->cont_dispatch without its FFI guards, which makes any
--     Lua metamethod on a cdata branch to address 0.
--   * ffi LOADS and STORES work, giving arbitrary read/write.
--   * BC_FUNCC (main+0x55628) calls a lua_CFunction as:
--         ldr x3,[x2,#0x28]   ; GCfuncC.f
--         mov x0,x23          ; the ONLY argument is lua_State *L
--         blr x3
--         sbfiz x28,x0,#3,#32 ; the return value is read as nresults
--   * Overwriting GCfunc+0x28 and calling that Lua function therefore
--     performs a native call with the VM's own register discipline.
--     Confirmed: jank_call_zero returned nresults=0 from a gadget.
--
-- TWO CALL FORMS
--
--   call0(target)         x0 = L (ignored by the target). For zero-argument
--                         functions. The return value must be small, because
--                         BC_FUNCC reads it as a result count - a Result of 0
--                         is ideal, which is what nn:: Initialize functions
--                         give on success.
--
--   call_ptr(target, ctrl) x0 = a buffer WE control, via a tail-call thunk:
--                             ldr x0,[x0,#0x18]   ; x0 = [L+0x18] = ctrl
--                             ldr x8,[x0]         ; x8 = [ctrl+0]  (vtable)
--                             ldr x4,[x8,#0x18]   ; x4 = callee
--                             br  x4              ; tail call, x0 = ctrl
--                         A TAIL call matters: entering a normal function
--                         mid-body would run an epilogue that restores
--                         x29/x30 from the VM's frame and return into
--                         garbage. With `br`, the callee's own `ret` goes
--                         straight back to BC_FUNCC.
--
-- WHY A COROUTINE: the thunk dereferences [L+0x18], so we must borrow a
-- lua_State field. Corrupting the main state is reckless, and we cannot
-- restore it between the callee returning and BC_FUNCC reloading L->base.
-- A coroutine has its own lua_State whose address `tostring` prints, so we
-- clobber THAT, run the call inside it, and restore afterwards. The GC is
-- stopped across the call because the borrowed field is GC-visible.

local log = require("bl.log")

local M = { FUNC_F = 0x28, L_SLOT = 0x18, VT_CALLEE = 0x18 }

local function u64(ffi, addr) return ffi.cast("uint64_t*", ffi.cast("uintptr_t", addr)) end

function M.obj_addr(v)
    local hex = tostring(v):match("[%a]+:%s*0x(%x+)")
    return hex and tonumber(hex, 16) or nil
end

-- A control block: the argument struct for the callee AND the fake vtable the
-- thunk walks. Both live in one buffer, which is also why the vtable pointer
-- sits at +0, where an output-pointer callee will happily overwrite it after
-- the call (it is only read before).
function M.ctrl(ffi, size)
    size = size or 0x200
    local buf = ffi.new("uint8_t[?]", size + 0x40)
    local raw = tonumber(ffi.cast("uintptr_t", buf))
    local addr = raw + (0x10 - raw % 0x10) % 0x10          -- 16-byte aligned
    return { buf = buf, addr = addr, size = size,
             u64 = function(off) return u64(ffi, addr + off) end }
end

-- target: absolute address. ctrl: a table from M.ctrl. vtable_at: where in
-- ctrl to place the fake vtable (default 0x80), so the callee's own struct
-- fields can occupy the start of the block.
function M.prepare(ctrl, target, vtable_at)
    vtable_at = vtable_at or 0x80
    ctrl.u64(0)[0] = ctrl.addr + vtable_at                  -- [ctrl+0] = vtable
    ctrl.u64(vtable_at + M.VT_CALLEE)[0] = target           -- [vtable+0x18] = callee
    return ctrl
end

local function hijack(ffi, victim, addr)
    local obj = M.obj_addr(victim)
    if not obj then return nil, "no GCfunc address" end
    local slot = u64(ffi, obj + M.FUNC_F)
    local saved = slot[0]
    slot[0] = ffi.cast("uint64_t", addr)
    return function() slot[0] = saved end
end

-- Zero-argument call: the target sees x0 = L and is expected to ignore it.
function M.call0(ffi, victim, target)
    local restore, why = hijack(ffi, victim, target)
    if not restore then return nil, why end
    local n
    local ok, err = pcall(function() n = select("#", victim()) end)
    restore()
    if not ok then return nil, "raised: " .. tostring(err) end
    return { ret = n }      -- nresults IS the return value (small values only)
end

-- Pointer-argument call through the thunk, inside a coroutine whose
-- lua_State we borrow.
-- ORDERING IS LOAD-BEARING. lua_State+0x18 is `gclist`, and for threads the
-- collector REWRITES that field on every propagation:
--     setgcrefr(th->gclist, g->gc.grayagain);
--     setgcref(g->gc.grayagain, o);
-- So the snapshot we restore is only valid if NO GC step can run between the
-- read and the write. Every allocation is a potential step, and tostring()
-- inside obj_addr/hijack allocates. A stale restore truncates the gray or
-- grayagain chain, stranding gray objects whose children are then swept while
-- still referenced - which surfaces much later as a corrupt gray head
-- faulting in propagatemark. The collector is therefore stopped BEFORE any
-- allocation, and the snapshot/restore window contains no allocation at all.
function M.call_ptr(ffi, victim, thunk, ctrl)
    collectgarbage("stop")
    local function resume_gc(a, b) collectgarbage("restart"); return a, b end

    local co = coroutine.create(function() return victim() end)
    local L = M.obj_addr(co)
    if not L then return resume_gc(nil, "no lua_State address for the coroutine") end
    local restore, why = hijack(ffi, victim, thunk)
    if not restore then return resume_gc(nil, why) end

    -- Preallocate everything the window needs; no allocation past this point.
    local slot = u64(ffi, L + M.L_SLOT)
    local borrowed = ffi.cast("uint64_t", ctrl.addr)
    local results = {}

    local saved_slot = slot[0]
    slot[0] = borrowed
    results[1], results[2] = coroutine.resume(co)
    slot[0] = saved_slot

    restore()
    collectgarbage("restart")

    if not results[1] then return nil, "resume failed: " .. tostring(results[2]) end
    -- The victim returns no values, so resume yields exactly `true`; the
    -- laundered BC_FUNCC result count is checked by the caller instead.
    return { ret = 0, L = L }
end

-- A two-register call with a laundered return. Ghidra confirms that the
-- launderer loads x1 from ctrl+0x38 and branches if it is zero, THEN loads
-- x0 from ctrl+0x50 and blr's ctrl+0x48. Hardware has confirmed the same
-- path with x1=1, but arbitrary x1 has not yet been device-tested.
--
-- IMPORTANT: x1=0 takes the failure branch, which returns -1 to BC_FUNCC
-- as a bogus result count. Decline before patching the function pointer.
function M.call2(ffi, victim, info, ctrl, target, arg0, arg1)
    local a1 = ffi.cast("uint64_t", arg1 or 0)
    if a1 == 0 then return nil, "launder gadget requires nonzero x1" end
    local off = info.off
    local vt = 0x80
    ctrl.u64(0)[0] = ctrl.addr + vt
    ctrl.u64(vt + M.VT_CALLEE)[0] = info.sdk_base + off.launder
    ctrl.u64(off.launder_arg1)[0] = a1                    -- exact x1
    ctrl.u64(off.launder_callee)[0] = ffi.cast("uint64_t", target)
    ctrl.u64(off.launder_arg0)[0] = ffi.cast("uint64_t", arg0 or 0)
    return M.call_ptr(ffi, victim, info.sdk_base + off.thunk_ptr, ctrl)
end

-- Device-tested form: x1=1, arg0 arbitrary. Native result is discarded.
function M.call1(ffi, victim, info, ctrl, target, arg0)
    return M.call2(ffi, victim, info, ctrl, target, arg0, 1)
end

function M.describe(info)
    return ("jffi: victim=GCfunc+%#x L_slot=+%#x thunk=sdk+%#x ret_zero=sdk+%#x"):format(
        M.FUNC_F, M.L_SLOT, info.off.thunk_ptr, info.off.ret_zero)
end

return M
